307	        return new ToStringCreator(this)
308	
309	            .append("id", this.getId())
310	            .append("new", this.isNew())
311	            .append("lastName", this.getLastName())
312	            .append("firstName", this.getFirstName())
313	            .append("address", this.address)
314	            .append("city", this.city)
315	            .append("telephone", this.telephone)
316	            .toString();
317	    }
